                name: "subfolder".to_string(),
                ipns_name: "k51qzi5uqu5dSUBFOLDERref456".to_string(),
                folder_key_encrypted: "00".to_string(),
                ipns_private_key_encrypted: "00".to_string(),
                created_at: 1700002000000,
                modified_at: 1700002000000,
