        // is Session::new(..).run()) so we can grab a Notifier and drive
        // inval_inode() from a worker thread fed by drain_filepointer_completions.
        let mut session = match fuser::Session::new(fs, &mount_path_clone, &options) {
            Ok(s) => s,
            Err(e) => {
                log::error!("FUSE mount error: {}", e);
                let _ = tx.send(Err(format!("FUSE mount error: {}", e)));
                return;
            }
        };
        let notifier = session.notifier();
        std::thread::Builder::new()
            .name("fuse-inval".to_string())
            .spawn(move || {
                while let Ok(ino) = inval_rx.recv() {
                    match notifier.inval_inode(ino, 0, 0) {
                        Ok(()) => log::info!("DIAG: inval_inode sent for ino {}", ino),
                        Err(e) => log::warn!("DIAG: inval_inode failed for ino {}: {}", ino, e),
                    }
                }
            })
            .ok();
        match session.run() {
            Ok(()) => { log::info!("FUSE filesystem unmounted cleanly"); let _ = tx.send(Ok(())); }
            Err(e) => { log::error!("FUSE mount error: {}", e); let _ = tx.send(Err(format!("FUSE mount error: {}", e))); }
        }
    })
    .map_err(|e| format!("Failed to spawn FUSE thread: {}", e))?;

